import{_ as e,c as a,o as r,ah as s,ai as i}from"./chunks/framework.BssxmkiH.js";const g=JSON.parse('{"title":"Cloud Settings","description":"","frontmatter":{},"headers":[],"relativePath":"cloud-settings.md","filePath":"cloud-settings.md"}'),o={name:"cloud-settings.md"};function d(n,t,l,h,c,u){return r(),a("div",null,t[0]||(t[0]=[s('<h1 id="cloud-settings" tabindex="-1">Cloud Settings <a class="header-anchor" href="#cloud-settings" aria-label="Permalink to “Cloud Settings”">​</a></h1><p><img src="'+i+'" alt="Clouds." loading="lazy"></p><p>Clouds are a key element in creating a realistic and dynamic sky. They can add depth, atmosphere, and visual interest to your scenes.</p><p>Fast Sky 2 doesn&#39;t render clouds as physically accurate volumetrics, instead it uses a faster volume-approximation technique to render the clouds. This allows for a good balance between visual quality and performance, making it suitable for a wide range of platforms and devices.</p><p>Fast Sky 2 supports up to 4 distinct cloud layers.</p><h2 id="main-settings" tabindex="-1">Main Settings <a class="header-anchor" href="#main-settings" aria-label="Permalink to “Main Settings”">​</a></h2><p>Controls the overall rendering of all cloud layers.</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Fast Mode</td><td>Renders the clouds at a fixed resolution of <strong>512x512</strong> or less, depending on your screen size. This drastically improves performance with a very minimal quality tradeoff.</td></tr><tr><td>Banding Reduction</td><td>Allows you to use a lower number of lightmarch steps for better quality-performance balance and to eliminate banding artifacts(mostly visible during sun rise/set). <br><br> When using <strong>BandingReduction.Dither</strong>, the cloud get jittered every frame, eliminating the banding artifacts. The jittering is usually not noticed but could be reducing by using <a href="https://docs.unity3d.com/6000.3/Documentation/Manual/urp/anti-aliasing.html" target="_blank" rel="noreferrer">Temporal Anti-aliasing(TAA)</a></td></tr><tr><td>Render Shadows</td><td>Enables the rendering of cloud shadows. You can control the area the cloud shadows by adding/using the <a href="./setup#setting-up-the-fast-sky-component">FastSkySceneConfig</a> component. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Shadow Resolution</td><td>Cloud shadows resolution, lower values gives better performance with a minor quality tradeoff.<br><br>This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Shadow Intensity</td><td>Controls the intensity of the cloud shadows.</td></tr><tr><td>Night Darken Factor</td><td>Controls the darkening of the clouds at night.</td></tr><tr><td>Night Absorption Multiplier</td><td>Controls the absorption of the clouds at night.</td></tr><tr><td>Night Opacity Multiplier</td><td>How much the clouds&#39; opacity is multiplied at night. Clouds closer to the moon is less influenced by this value.</td></tr><tr><td>Forward Scattering</td><td>Light scattering coefficient. This is responsible for the bright, white appearance of clouds and the glare around the sun.</td></tr></tbody></table><h2 id="cloud-layer" tabindex="-1">Cloud Layer <a class="header-anchor" href="#cloud-layer" aria-label="Permalink to “Cloud Layer”">​</a></h2><p>Each cloud layer has its own settings that controls its appearance and movement. You can use different settings for each layer to create a more dynamic and interesting sky.</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Enabled</td><td>Controls the enable state of this cloud layer. <br><br> This is a <a href="./glossary#static-parameters">static</a> and <a href="./glossary#performance-sensitive-parameters">performance sensitive</a> parameter.</td></tr><tr><td>Noise Type</td><td>The <a href="#noise-type">noise type</a> used for this cloud layer. <br><br> This is a <a href="./glossary#static-parameters">static</a> parameter.</td></tr><tr><td>3D</td><td>Enables 3D sampling, which is a little more expensive but allows curvatures &gt; 0.5 without stretching artifacts along the y-axis. <br><br>This paramter is <a href="./glossary#static-parameters">static</a> <a href="./glossary#performance-sensitive-parameters">performance sensitive</a>, but is quite minimal.</td></tr><tr><td>Scale</td><td>Scale of the noise texture sampling. Higher values result in smaller clouds, lower values in larger cloud shapes.</td></tr><tr><td>Coverage</td><td>The coverage of the clouds. Higher values result in more clouds coverage, fewer for lower values.</td></tr><tr><td>Opacity</td><td>Controls the opacity / transparancy of this cloud layers.</td></tr><tr><td>Thickness</td><td>The thickness of the clouds. Higher values result in smoother cloud features, but requires higher <strong>lightmarch steps</strong> to look good.</td></tr><tr><td>Lightmarch Steps</td><td>The number of steps to use for lightmarching the clouds. Higher values prevents banding, but are more expensive to render. You can use the <a href="#main-settings">BandingReduction</a> to minimize it. You should leave this value as 0 if you&#39;re rendering a flat cloud layer. <br><br> This is parameter is <a href="./glossary#performance-sensitive-parameters">performance sensitive</a></td></tr><tr><td>Absorption</td><td>The absorption/darkening of light as it travels through the cloud.</td></tr><tr><td>Absorption Spread</td><td>Spreads the absorption effect across the cloud&#39;s density.</td></tr><tr><td>Color</td><td>The color of the cloud layer.</td></tr><tr><td>Light Transmittance</td><td>How much this cloud layer is affected by the atmospheric scattering. Higher values result in reddish(depending on your extinction parameters) sunrise/sunset effect.</td></tr><tr><td>Curvature</td><td>Controls curvature of the clouds along the atmosphere. Higher values (0.5 - 0.6) results in stretching artifacts when not using 3D sampling.</td></tr><tr><td>Wind Vector</td><td>The direction and speed of the clouds.</td></tr><tr><td>Detail Scale</td><td>The scale of the detail noise. Higher values result in smaller details.</td></tr><tr><td>Detail Weight</td><td>The erosion strength of the detail noise. Higher values result in more details.</td></tr><tr><td>Detail Wind Speed</td><td>The speed of the detail noise movement relative to the &#39;WindVector&#39; parameter.</td></tr><tr><td>Zenith Mask</td><td>Masks the clouds towards the zenith.</td></tr><tr><td>Horizon Mask</td><td>Masks the clouds towards the horizon.</td></tr><tr><td>Zenith Mask Blend</td><td>The blend distance/sharpness of the zenith mask.</td></tr><tr><td>Horizon Mask Blend</td><td>The blend distance/sharpness of the horizon mask.</td></tr></tbody></table><h2 id="noise-type" tabindex="-1">Noise Type <a class="header-anchor" href="#noise-type" aria-label="Permalink to “Noise Type”">​</a></h2><p>The noise type determines the look of the cloud shapes.</p><table tabindex="0"><thead><tr><th>Property</th><th>Function</th></tr></thead><tbody><tr><td>Worley</td><td>Bubbly and distinct.</td></tr><tr><td>Billow</td><td>Much more bubbly and less distinct.</td></tr><tr><td>Perlin</td><td>Light and distinct.</td></tr><tr><td>Value</td><td>Dense and very distinct.</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Distinct in this sense means clouds formations are physically separate from each other.</p></div>',15)]))}const m=e(o,[["render",d]]);export{g as __pageData,m as default};
